SELECT set_config('app.seed_mode', 'off', true);

-- ===== rls_09_links_and_writes =====
-- ป้าย assertion: L = ผูกลูกค้าข้ามสาขา (V-8 · IN-4) · X = ตารางที่เขียนได้เฉพาะ trigger/RPC ·
--                 Y = คอลัมน์ owner/ทีม/สาขา · Z = เส้นทางเขียนที่ต้องสำเร็จ (trigger DEFINER) ·
--                 Q = MFA/ขอบเขต · V = anon · service_role

-- fixture เพิ่ม: visit นิรนามของสาขา TR2 ที่ P13 (BRANCH_MANAGER@TR1 + STAFF@TR2) เป็นผู้รับ
INSERT INTO crm.visits (id, organization_id, visit_no, branch_id, channel_code, status, queue_no, customer_id, interest_code,
                        started_at, service_started_at, owner_staff_id, closed_by_system, created_at, created_by)
VALUES ('7a000000-0000-4000-8000-00000000030a', '7a000000-0000-4000-8000-000000000001', 'V-TR2-000000-002',
        '7a000000-0000-4000-8000-000000000012', 'WALK_IN', 'IN_SERVICE', 2, NULL, 'INQUIRY',
        now() - interval '10 minutes', now() - interval '10 minutes', '7a000000-0000-4000-8000-000000000113', false,
        now() - interval '10 minutes', '7a000000-0000-4000-8000-000000000113');

-- ---------------------------------------------------------------------------
-- L · ผูกลูกค้าข้ามสาขาด้วยการ UPDATE customer_id (ข้อ 6.6 · 8.0 · 19.3 ข้อ 4)
-- ---------------------------------------------------------------------------
SELECT test.login_as('rls.p13@example.com', 'aal2');
SELECT test.assert_eq(test.count_rows($$SELECT id FROM crm.customers WHERE id = '7a000000-0000-4000-8000-000000000201'$$), 1::bigint,
    'L01 BM1ST2 aal2 อ่านลูกค้า TR1 ได้ (จากบทบาทผู้จัดการสาขา TR1)');
SELECT test.assert_denied($$UPDATE crm.visits SET customer_id = '7a000000-0000-4000-8000-000000000201' WHERE id = '7a000000-0000-4000-8000-00000000030a'$$,
    'T26', 'V-8 ระบุลูกค้าของสาขา TR1 ให้ visit ของ TR2 (ต้องใช้ api.link_customer_to_branch)');
SELECT test.assert_eq(test.exec_count($$UPDATE crm.visits SET customer_id = '7a000000-0000-4000-8000-000000000203' WHERE id = '7a000000-0000-4000-8000-00000000030a'$$), 1::bigint,
    'V-8 ผ่าน: ลูกค้าที่เชื่อมสาขา TR2 อยู่แล้ว');
INSERT INTO crm.interactions (branch_id, channel_code, direction, interaction_type_code, summary)
    VALUES ('7a000000-0000-4000-8000-000000000012', 'LINE', 'OUTBOUND', 'MESSAGE', 'นิรนาม TR2 (rls_09)');
SELECT test.assert_denied($$UPDATE crm.interactions SET customer_id = '7a000000-0000-4000-8000-000000000201' WHERE summary = 'นิรนาม TR2 (rls_09)'$$,
    'T26', 'IN-4 ใส่ลูกค้าของสาขา TR1 ให้ interaction นิรนามของ TR2');
SELECT test.assert_eq(test.exec_count($$UPDATE crm.interactions SET customer_id = '7a000000-0000-4000-8000-000000000203' WHERE summary = 'นิรนาม TR2 (rls_09)'$$), 1::bigint,
    'IN-4 ผ่าน: ลูกค้าที่เชื่อมสาขา TR2 อยู่แล้ว');
SELECT test.assert_denied($$INSERT INTO crm.tasks (task_type_code, title, customer_id, branch_id, due_at)
    VALUES ('OTHER', 'งานลูกค้า TR1 ที่สาขา TR2', '7a000000-0000-4000-8000-000000000201', '7a000000-0000-4000-8000-000000000012', now() + interval '1 day')$$,
    NULL, 'L02 สร้างงานของลูกค้า TR1 ที่สาขา TR2 (แม่แบบ C)');
SELECT test.assert_denied($$INSERT INTO crm.transaction_refs (customer_id, branch_id, transaction_type_code, source_system_code, external_no, transacted_at)
    VALUES ('7a000000-0000-4000-8000-000000000201', '7a000000-0000-4000-8000-000000000012', 'SALE', 'MANUAL', 'RLS09-TXN-1', now())$$,
    NULL, 'L03 ผูกธุรกรรมของลูกค้า TR1 ที่สาขา TR2');
SELECT test.assert_denied($$INSERT INTO crm.opportunities (customer_id, origin_channel_code, branch_id, priority_code, next_action, next_action_type_code, next_action_at)
    VALUES ('7a000000-0000-4000-8000-000000000201', 'LINE', '7a000000-0000-4000-8000-000000000012', 'NORMAL', 'x', 'CALL', now() + interval '1 day')$$,
    NULL, 'L04 สร้างโอกาสขายของลูกค้า TR1 ที่สาขา TR2');

-- BUSINESS_ADMIN (visit.update ที่ scope ORGANIZATION) ผูกได้ตามข้อ 8.0 (ข้อยกเว้น scope G)
SELECT test.login_as('rls.p02@example.com', 'aal2');
SELECT test.assert_eq(test.exec_count($$UPDATE crm.visits SET customer_id = '7a000000-0000-4000-8000-000000000201' WHERE id = '7a000000-0000-4000-8000-00000000030a'$$), 1::bigint,
    'L05 BA (scope G) เปลี่ยนลูกค้าของ visit ข้ามสาขาได้');
SELECT test.login_as('rls.p13@example.com', 'aal1');
